NAME = 'vlsJoNT: Het Nieuwe Testament by Nicolaas De Jonge'
BOOK = 'Mark'

CHAPTERS = {
    1: {
        1: 'Begin van het Evangelie van Jezus Christus, den Zoon van God.',
        2: 'Zooals geschreven is in den profeet Jesaja: Zie, Ik zend mijn boodschapper voor u heen, die uw weg bereiden zal;',
        3: 'een stem van een die roept in de woestijn: Bereidt den weg des Heeren, maakt zijn paden recht!',
        4: 'Johannes was doopende in de woestijn, en predikende den doop der boetvaardigheid tot vergiffenis der zonden.',
        5: 'En tot hem ging uit het geheele land van Judea, en al de Jerusalemmers, en zij werden door hem gedoopt in de rivier den Jordaan, belijdende hun zonden.',
        6: 'En Johannes was bekleed met kemelshaar, en met een lederen gordel om zijn lenden, en hij at sprinkhanen en wilden honig.',
        7: 'En hij predikte, zeggende: Na mij komt Hij, die machtiger is dan ik, wien ik niet waardig ben, nederbukkende, den riem zijner schoenen los te maken;',
        8: 'ik heb u gedoopt met water, maar Hij zal u doopen met den Heiligen Geest.',
        9: 'En het geschiedde in die dagen dat Jezus kwam van Nazaret in Galilea, en gedoopt werd in den Jordaan door Johannes.',
        10: 'En terstond, terwijl Hij opklom uit het water, zag hij de hemelen scheuren en den Geest zooals een duive op Hem nederdalen.',
        11: 'En een stem kwam uit de hemelen: Gij zijt mijn Zoon, de Beminde, in U heb Ik welbehagen!',
        12: 'En terstond voerde de Geest Hem uit naar de woestijn;',
        13: 'en Hij was in de woestijn veertig dagen lang, bekoord van den Satan; en Hij was bij de wilde beesten, en de engelen dienden Hem.',
        14: 'Nadat nu Johannes was overgeleverd, kwam Jezus naar Galilea, predikende het Evangelie van het koninkrijk Gods, zeggende:',
        15: 'De tijd is vervuld en het koninkrijk Gods nabij! doet boetvaardigheid en gelooft in het Evangelie!',
        16: 'En langs de zee van Galilea gaande, zag Hij Simon en Andreas, den broeder van Simon, het net in de zee werpen, want zij waren visschers.',
        17: 'En Jezus zeide tot hen: Komt achter Mij, en Ik zal u visschers van menschen doen worden!',
        18: 'En terstond lieten zij hun netten achter en volgden Hem.',
        19: 'En vandaar een weinig voortgaande zag Hij Jakobus, den zoon van Zebedeüs, en Johannes zijn broeder, die in het schip de netten herstelden.',
        20: 'En terstond riep Hij hen, en zij lieten hun vader Zebedeüs in het schip met de knechten, en gingen heen, Hem achterna.',
        21: 'En zij kwamen naar Kapernaüm, en terstond ging Hij op den sabbat in de synagoge om onderwijs te geven.',
        22: 'En zij stonden verbaasd over zijn onderwijs, want Hij leerde hen als een machthebbende, en niet zooals de schriftgeleerden.',
        23: 'En er was in hun synagoge een mensch met een onzuiveren geest, en die schreeuwde en zeide:',
        24: 'Wat hebben wij met U te doen, Jezus de Nazarener? Zijt Gij gekomen om ons te verderven? We weten wie Gij zijt! — de Heilige Gods!',
        25: 'En Jezus bestrafte hem, zeggende: Zwijg stil en ga van hem uit!',
        26: 'En de onzuivere geest smeet hem heen en weer, en met een groote stem schreeuwende ging hij van hem uit.',
        27: 'En allen stonden verbaasd, zoodat zij onder malkander vroegen, zeggende: Wat is dat? Een nieuwe leer! met macht gebiedt Hij zelfs de onzuivere geesten, en die gehoorzamen Hem!',
        28: 'En zijn gerucht ging terstond overal uit, door het geheele omliggende land van Galilea.',
        29: 'En terstond uit de synagoge gegaan zijnde kwamen zij naar het huis van Simon en van Andreas, met Jakobus en Johannes.',
        30: 'De schoonmoeder nu van Simon lag aan de koorts, en terstond spraken ze tot Hem over haar.',
        31: 'En tot haar gaande greep Hij haar hand en richtte haar op; en de koorts verliet haar terstond en zij bediende hen.',
        32: 'Toen het nu avond was geworden en de zon was ondergegaan, brachten ze tot Hem allen die ziek en van booze geesten bezeten waren.',
        33: 'En de geheele stad was samenvergaderd bij de deur.',
        34: 'En Hij genas er velen die krank waren aan allerlei ziekten, en vele booze geesten wierp Hij uit, en liet de booze geesten niet toe te spreken, omdat zij Hem kenden.',
        35: 'En vroeg, toen het nog diep in den nacht was, opgestaan zijnde, ging Hij uit en begaf zich naar een eenzame plaats, en daar bad Hij.',
        36: 'En Simon, en die met hem waren, volgden Hem na,',
        37: 'en vonden Hem, en zeiden tot Hem: Allen zoeken u!',
        38: 'En Hij zeide tot hen: Laat ons heengaan naar de nabijgelegen marktplaatsen, opdat Ik ook daar predike, want daartoe ben Ik uitgegaan.',
        39: 'En Hij ging, predikende in hun synagogen door geheel Galilea, en wierp de booze geesten uit.',
        40: 'En er kwam een melaatsche tot Hem, die Hem bad en op de knieën vallende tot Hem zeide: Als Gij wilt, kunt Gij mij zuiveren!',
        41: 'En Jezus met medelijden bewogen zijnde, strekte zijn hand uit, raakte hem aan en zeide: Ik wil, word gezuiverd!',
        42: 'En terstond, als Hij dit gezegd had, ging de melaatschheid van hem en hij werd gezuiverd.',
        43: 'En Hij verbood hem streng en zond hem terstond weg,',
        44: 'en zeide tot hem: Zie toe, zeg aan niemand iets, maar ga heen, vertoon u aan den priester en offer voor uw zuivering wat Mozes geboden heeft, hun tot een getuigenis!',
        45: 'Maar hij ging uit en begon veel te verkondigen en de zaak te verbreiden, zoodat Jezus niet meer openlijk naar de stad kon komen; maar Hij was buiten in eenzame plaatsen; en zij kwamen tot Hem van alle kanten.',
    },
    2: {
        1: 'En na eenige dagen kwam Jezus wederom naar Kapernaüm, en men hoorde dat Hij te huis was.',
        2: 'En velen verzamelden zich, zoodat er geen plaats meer was, zelfs niet bij de deur; en Hij sprak het woord tot hen.',
        3: 'En zij kwamen en brachten tot Hem een lamme, die door vier gedragen werd.',
        4: 'En omdat zij niet bij Hem konden komen ter oorzake van de menigte, namen zij het dak weg waar Hij was, en toen zij een opening gemaakt hadden lieten zij het bed naar beneden, waar de lamme op lag.',
        5: 'En Jezus hun geloof ziende, zeide tot den lamme: Zoon, de zonden zijn u vergeven!',
        6: 'Er waren nu sommigen van de schriftgeleerden daar gezeten, die in hun harten redeneerden:',
        7: 'Hoe spreekt deze alzoo? Hij lastert! — Wie kan zonden vergeven, dan God alleen?',
        8: 'En terstond bekende Jezus in zijn geest dat zij alzoo redeneerden in zich zelven, en zeide tot hen: Wat beredeneert gij deze dingen in uw harten?',
        9: 'Wat is gemakkelijker, tot den lamme te zeggen: Uw zonden zijn vergeven, of te zeggen: Sta op, en neem uw bed op en ga heen!',
        10: 'Maar opdat gij weten moogt dat de Zoon des menschen macht heeft op aarde om zonden te vergeven, — toen zeide Hij tot den lamme:',
        11: 'Ik zeg u, sta op, neem uw bed op en ga heen naar uw huis!',
        12: 'En hij stond op en nam terstond het bed op en ging uit voor aller oogen, zoodat allen verbaasd waren en God de glorie gaven, zeggende: Zoo iets hebben wij nooit gezien!',
        13: 'En Hij ging wederom uit naar de zee en al het volk kwam tot Hem en Hij onderwees hen.',
        14: 'En voorbijgaande zag Hij Levi, den zoon van Alfeüs, aan het tolhuis zitten, en Hij zeide tot hem: Volg Mij na! — En opstaande volgde hij Hem na.',
        15: 'En het geschiedde dat Hij aanlag in Levi’s huis, en veel tollenaars en zondaars lagen met Jezus en zijn discipelen mede aan; want er waren er velen en zij waren Hem nagevolgd.',
        16: 'En de schriftgeleerden en fariseërs, als ze zagen dat Hij at met de tollenaars en zondaars, zeiden tot zijn discipelen: Waarom eet en drinkt Hij met de tollenaars en zondaars?',
        17: 'En Jezus dit hoorende zeide tot hen: Niet de gezonden hebben een geneesmeester noodig, maar de zieken; Ik ben niet gekomen om rechtvaardigen te roepen, maar zondaars!',
        18: 'En de discipelen van Johannes en van de fariseërs waren vastende, en zij kwamen en zeiden tot Hem: Waarom vasten de discipelen van Johannes en die der fariseërs, maar uw discipelen vasten niet?',
        19: 'En Jezus zeide tot hen: Kunnen dan de bruiloftsgasten vasten terwijl de bruidegom bij hen is? Zoolang zij den bruidegom bij zich hebben, kunnen zij niet vasten!',
        20: 'maar er zullen dagen komen, als de bruidegom van hen is weggenomen, en dan zullen zij vasten in dien dag!',
        21: 'Niemand toch naait een stuk ongekrompen laken op een oud kleed; anders scheurt het ingezette stuk, dat nieuw is, van het oude af, en de scheur wordt erger.',
        22: 'En niemand giet jongen wijn in oude zakken, anders doet de wijn de zakken barsten, en de wijn wordt uitgestort, en de zakken gaan verloren; maar jongen wijn moet men in nieuwe zakken gieten.',
        23: 'En het geschiedde dat Hij op den sabbat door het korenveld ging, en zijn discipelen begonnen al gaande, aren te plukken.',
        24: 'En de fariseërs zeiden tot Hem: Zie, waarom doen zij op den sabbat wat niet geoorloofd is?',
        25: 'En Hij zeide tot hen: Hebt gij nooit gelezen, wat David gedaan heeft, toen hij gebrek had en honger had, en zij die met hem waren?',
        26: 'Hoe hij is ingegaan in het huis Gods, ten tijde van Abjathar den hoogepriester, en de toonbrooden heeft gegeten, die niemand mag eten dan alleen de priesters, en dat hij gegeven heeft ook aan degenen die met hem waren?',
        27: 'En Hij zeide tot hen: De sabbat is gemaakt om den mensch, en niet de mensch om den sabbat.',
        28: 'Zoo is de Zoon des menschen Heer, ook van den sabbat!',
    },
    3: {
        1: 'En Jezus ging wederom naar de synagoge, en daar was een mensch die een stijve hand had.',
        2: 'En zij letten op Hem of Hij op den sabbat hem zou genezen, opdat ze Hem mochten beschuldigen.',
        3: 'En Hij zeide tot den mensch die de stijve hand had: Sta op in het midden!',
        4: 'En Hij zeide tot hen: Is het geoorloofd op den sabbat goed te doen of kwaad te doen? een ziel te behouden of te dooden? — Maar zij zwegen stil.',
        5: 'En als Hij rondom hen aangezien had met toorn, te gelijk bedroefd over de verharding van hun harte, zeide Hij tot den mensch: Steek uw hand uit! — En hij stak ze uit en zijn hand was genezen.',
        6: 'En de fariseërs gingen uit en hielden terstond met de herodianen raad tegen Hem, hoe ze Hem ten val brengen zouden.',
        7: 'En Jezus vertrok met zijn discipelen naar de zee, en een groote menigte van Galilea en van Judea volgde Hem,',
        8: 'en van Jerusalem, en van Idumea, en van over den Jordaan, en van bij Tyrus en Sidon; een groote menigte, die gehoord had hoe groote dingen Hij deed, kwam tot Hem.',
        9: 'En Hij zeide tot zijn discipelen dat er een scheepken bij Hem moest blijven wegens de schare; opdat ze Hem niet zouden verdringen;',
        10: 'want velen genas Hij, zoodat al wie krankheden hadden, op Hem aandrongen, om Hem aan te raken.',
        11: 'En de onzuivere geesten, als ze Hem zagen, vielen voor Hem neder, en schreeuwden, zeggende: Gij zijt de Zone Gods!',
        12: 'En Hij gebood hun scherpelijk dat zij Hem niet openbaar zouden maken.',
        13: 'En Hij klom op een berg en riep tot zich die Hij zelf wilde, en zij kwamen tot Hem.',
        14: 'En Hij stelde er twaalf aan, om met Hem te zijn, en om die uit te zenden om te prediken,',
        15: 'en om macht te hebben de ziekten te genezen en om de booze geesten uit te werpen.',
        16: 'En Hij stelde deze twaalf aan, en gaf aan Simon den naam Petrus,',
        17: 'en Jakobus den zoon van Zebedeüs en Johannes den broeder van Jakobus, en Hij gaf hun den naam Boanerges, dat is: Zonen des donders;',
        18: 'en Andreas, en Filippus, en Bartholomeüs, en Mattheüs, en Thomas, en Jakobus den zoon van Alfeüs, en Thaddeüs, en Simon den Kananeër,',
        19: 'en Judas Iskariot, die Hem ook verraden heeft.',
        20: 'En zij kwamen in huis, en wederom vergaderde een menigte, zoodat zij zelfs geen brood konden eten.',
        21: 'En als zijn familie dit gehoord had, kwamen zij om Hem te vatten, want zij zeiden dat Hij uitzinnig was.',
        22: 'En de schriftgeleerden, die van Jerusalem afgekomen waren, zeiden: Hij heeft Beëlzebul, en door den overste der booze geesten werpt Hij de booze geesten uit!',
        23: 'En Hij riep hen tot zich en sprak in gelijkenissen tot hen: Hoe kan Satan den Satan uitwerpen?',
        24: 'En als een koninkrijk tegen zich zelf verdeeld is, dan kan dat koninkrijk niet bestaan.',
        25: 'En als een huisgezin tegen zich zelf verdeeld is, dan zal dat huisgezin niet kunnen bestaan.',
        26: 'En als de Satan tegen zich zelven opstaat, dan is hij verdeeld en kan hij niet bestaan, maar heeft een einde.',
        27: 'Doch niemand kan ingaan in het huis van een sterke en zijn huisraad rooven als hij niet eerst den sterke vastbindt; en dan zal hij zijn huis berooven.',
        28: 'Voorwaar, Ik zeg ulieden: Al de zonden en de lasteringen, waarmede zij zullen gelasterd hebben, zullen aan de kinderen der menschen vergeven worden,',
        29: 'maar zoo wie tegen den Heiligen Geest zal lasteren, — hij heeft geen vergiffenis in eeuwigheid, maar hij zal schuldig zijn aan een eeuwige zonde.',
        30: 'Want zij zeiden: Hij heeft een onzuiveren geest!',
        31: 'En zijn moeder kwam, met zijn broeders, en buiten staande zonden zij tot Hem, en riepen Hem.',
        32: 'En er zat een menigte volks rondom Hem, en zij zeiden tot Hem: Zie, uw moeder en uw broeders daarbuiten zoeken U!',
        33: 'En Hij antwoordde en zeide tot hen: Wie zijn mijn moeder of mijn broeders?;',
        34: 'En rondom ziende, op degenen die om Hem heen zaten, zeide Hij: Ziet, mijn moeder en mijn broeders!',
        35: 'Want al wie den wil van God doet, die is mijn broeder, en zuster, en moeder.',
    },
    4: {
        1: 'En wederom begon Jezus onderwijs te geven bij de zee, en tot Hem vergaderde zeer veel volk, zoodat Hij in het schip ging en op zee ging zitten. En al het volk was aan de zee, op het land.',
        2: 'En Hij onderwees hen in gelijkenissen vele dingen, en Hij zeide tot hen in zijn onderwijs:',
        3: 'Luistert! — Ziet, de zaaier ging uit om te zaaien.',
        4: 'En het geschiedde, als hij zaaide, dat er een deel bij den weg viel, en de vogels kwamen en pikten dat op.',
        5: 'En een ander deel viel op den rotsgrond, waar het niet veel aarde had, en terstond kwam het op, omdat het geen diepte van aarde had.',
        6: 'Maar toen de zon opging verbrandde het, en omdat het geen wortel had verdorde het.',
        7: 'En een ander deel viel tusschen de doornen, en de doornen schoten op, en verstikten het, en het gaf geen vrucht.',
        8: 'En een ander deel viel op den goeden grond en gaf een vrucht die opschoot en groeide, en bracht op tot dertig– en tot zestig– en tot honderdvoud.',
        9: 'En Hij zeide: Wie ooren heeft om te hooren, die hoore!',
        10: 'En toen Hij alleen was vroegen zij, die bij Hem waren met de twaalven, Hem naar de gelijkenis.',
        11: 'En Hij zeide tot hen: Aan ulieden is de verborgenheid van het koninkrijk Gods te verstaan gegeven, maar dezen die buiten zijn, geschiedt alles in gelijkenissen,',
        12: 'opdat zij ziende zien, en niet opmerken, en hoorende hooren, en niet verstaan, opdat zij niet misschien zich zouden bekeeren en hun vergiffenis geschiede!',
        13: 'En Hij zeide tot hen: Weet gij deze gelijkenis niet? En hoe zult gij dan al de gelijkenissen verstaan?',
        14: 'De zaaier zaait het woord.',
        15: 'Dezen nu zijn het die bij den weg gezaaid zijn, waar het woord gezaaid wordt, en als zij het gehoord hebben, de Satan terstond komt en het woord wegneemt, dat in hen gezaaid is.',
        16: 'En zoo zijn ook dezen die op den rotsgrond worden gezaaid, die, als zij het woord gehoord hebben, het terstond met blijdschap aannemen;',
        17: 'doch zij hebben geen wortel in zich zelven, maar zijn voor een tijd; daarna als er verdrukking komt of vervolging om des woords wil, dan worden zij terstond geërgerd.',
        18: 'En anderen zijn het die tusschen de doornen gezaaid zijn. Dezen zijn het die het woord gehoord hebben,',
        19: 'en de zorgen des tijds, en de verleiding des rijkdoms, en de begeerte naar de andere dingen, komen binnen en verstikken het woord, en het wordt onvruchtbaar.',
        20: 'En dezen zijn het die op den goeden grond zijn gezaaid, die het woord hooren, en aannemen, en vrucht dragen in dertig–, en in zestig–, en in honderdvoudige mate.',
        21: 'En Hij zeide tot hen: De lamp komt toch niet om onder een korenvat of onder een bed gezet te worden? Is het niet, om op een kandelaar gezet te worden?',
        22: 'Want er is niets verborgen, dan om openbaar te worden, en er gebeurt niets in het geheim, dan om aan het licht te komen.',
        23: 'Als iemand ooren heeft om te hooren, die hoore!',
        24: 'En Hij zeide tot hen: Ziet toe, wat gij hoort! Met de mate waarmede gij meet, zal u gemeten worden, en u zal nog toegevoegd worden!',
        25: 'Want wie heeft, hem zal gegeven worden; en wie niet heeft, ook wat hij heeft zal van hem weggenomen worden.',
        26: 'En Hij zeide: Alzoo is het koninkrijk Gods, gelijk wanneer een mensch het zaad in den grond geworpen heeft,',
        27: 'en slaapt, en opstaat, nacht en dag, en het zaad spruit voort en wordt lang hij weet zelf niet hoe.',
        28: 'Vanzelf toch brengt de aarde vrucht voort; eerst een stengel, dan een aar, dan volkomen graan in de aar.',
        29: 'En als de vrucht het toelaat, zendt hij er terstond de sikkel in, omdat de oogst is gekomen.',
        30: 'En Hij zeide: Hoe zullen wij het koninkrijk Gods vergelijken, of in welke gelijkenis zullen wij het voorstellen?',
        31: 'Als een mosterdzaad, dat, als het in de aarde gezaaid wordt, het kleinste is van al de zaden op de aarde,',
        32: 'en als het gezaaid is, schiet het op en het wordt het grootste van de moeskruiden, en maakt groote takken, zoodat onder zijn schaduw de vogelen des hemels kunnen verschuilen.',
        33: 'En in veel zulke gelijkenissen sprak Hij tot hen het woord, naar dat zij het konden verstaan;',
        34: 'maar zonder gelijkenis sprak Hij tot hen niet, maar afzonderlijk verklaarde Hij alles voor zijn discipelen.',
        35: 'En Hij zeide tot hen, op denzelfden dag, toen het avond was geworden: Laat ons overgaan, naar den anderen kant!',
        36: 'En het volk verlatende namen zij Hem, zooals Hij was, in het schip; en er waren andere schepen bij Hem.',
        37: 'En er kwam een groote stormvlaag, en de golven sloegen over in het schip, zoodat het schip vol werd.',
        38: 'En Hij was in het achterschip slapende op het kussen; en zij maakten Hem wakker en zeiden tot Hem: Meester! trekt Gij het U niet aan, dat wij vergaan?',
        39: 'En wakker geworden zijnde, bestrafte Hij den wind en zeide tot de zee: Zwijg, wees stil! — En de wind ging liggen, en er kwam een groote stilte.',
        40: 'En Hij zeide tot hen: Wat zijt gij zoo bevreesd? Hoe, hebt gij geen geloof?',
        41: 'En zij vreesden met groote vreeze en zeiden tot malkander: Wie is deze toch, dat zelfs de wind en de zee Hem gehoorzamen?',
    },
    5: {
        1: 'En zij kwamen naar den anderen kant van de zee, naar het land der Gerasenen.',
        2: 'En toen Hij uit het schip gegaan was, kwam Hem terstond uit de grafsteden een mensch te gemoet, met een onzuiveren geest,',
        3: 'die zijn woonplaats had in de grafsteden; en zelfs met een ketting kon niemand hem meer binden,',
        4: 'omdat hij dikwijls met voetboeien en kettingen was gebonden geweest; en de kettingen werden door hem gebroken en de voetboeien verbrijzeld, en niemand kon hem temmen.',
        5: 'En altijd, nacht en dag, in de grafsteden en op de bergen zijnde, schreeuwde hij en sloeg zich zelven met steenen.',
        6: 'En Jezus van verre ziende, liep hij toe en boog zich voor Hem,',
        7: 'en schreeuwende met een groote stem, zeide hij: Wat heb ik met U te doen, Jezus, Zoon van God den Allerhoogste? Ik bezweer U bij God, pijnig mij niet!',
        8: 'Want Hij zeide tot hem: Gij onzuivere geest, ga uit den mensch!',
        9: 'Èn Hij vroeg hem: Hoe is uw naam? — En hij zeide tot Hem: Mijn naam is Legioen, want we zijn met ons velen!',
        10: 'En hij verzocht Hem zeer dat Hij hem niet buiten het land zou jagen.',
        11: 'Er was nu daar bij den berg een groote kudde varkens weidende.',
        12: 'En al de booze geesten verzochten Hem zeggende: Zend ons naar de varkens, opdat wij daarin gaan!',
        13: 'En Jezus liet hun dat terstond toe. En de onzuivere geesten gingen uit naar de varkens, en de kudde stortte van de steilte af naar de zee, omtrent twee duizend, en ze versmoorden in de zee.',
        14: 'En die ze weidden vluchtten weg en boodschapten het in de stad en op het land; en zij kwamen zien wat er gebeurd was.',
        15: 'En zij kwamen tot Jezus, en zagen den bezetene, die het Legioen gehad had, zitten, gekleed en goed bij zijn verstand, en zij werden bevreesd.',
        16: 'En die het gezien hadden, vertelden hun hoe het den bezetene gegaan was en van de varkens.',
        17: 'En zij begonnen Hem te verzoeken van hun grenzen weg te gaan.',
        18: 'En toen Hij naar het schip ging, verzocht Hem degene die bezeten was geweest, om bij Hem te mogen zijn.',
        19: 'Doch Jezus liet hem dat niet toe, maar zeide tot hem: Ga naar uw huis, tot uw familie, en vertel hun wat groote dingen de Heere u gedaan heeft en dat Hij zich over u ontfermd heeft!',
        20: 'En hij ging weg en begon te prediken in Dekapolis wat groote dingen Jezus hem gedaan had. En allen verwonderden zich.',
        21: 'En als Jezus wederom in het schip naar den anderen kant was overgevaren, vergaderde een groote schare bij Hem, en Hij was bij de zee.',
        22: 'En er kwam een van de oversten der synagoge, met name Jaïrus, en Hem ziende, viel hij aan zijn voeten,',
        23: 'en verzocht Hem dringend, zeggende: Mijn dochterken ligt in haar uiterste; kom toch, leg de handen op haar, opdat zij gezond worde en leve!',
        24: 'En Hij ging met hem, en een groote menigte volgde Hem en zij verdrongen Hem.',
        25: 'En een vrouw, die twaalf jaar lang het bloedvloeien gehad had,',
        26: 'en veel geleden had van veel geneesmeesters, en al wat zij had er aan te koste gelegd had, en die niets beter maar eerder erger geworden was,',
        27: 'kwam, toen zij van Jezus gehoord had, onder de menigte van achter en raakte zijn kleed aan;',
        28: 'want zij zeide: Als ik ook zijn kleederen maar aanraak, dan zal ik gezond worden!',
        29: 'En terstond hield haar bloedvloeiing op, en zij gevoelde aan haar lichaam dat zij genezen was van de kwaal.',
        30: 'En terstond bemerkte Jezus in zich zelven de kracht die van Hem uitgegaan was, en Hij keerde zich om in de menigte en zeide: Wie heeft mijn kleederen aangeraakt?',
        31: 'En zijn discipelen zeiden tot Hem: Gij ziet dat de menigte U verdringt, en Gij zegt: Wie heeft Mij aangeraakt?',
        32: 'En Hij zag rond om haar te zien die dit gedaan had.',
        33: 'De vrouw nu, bevreesd en bevende zijnde, en weten de wat aan haar gebeurd was, kwam en viel voor Hem neder en zeide Hem de gansche waarheid.',
        34: 'En Hij zeide tot haar: Dochter, uw geloof heeft u gezond gemaakt! ga heen in vrede en wees genezen van uw kwaal!',
        35: 'Terwijl Hij nog sprak kwamen er van den overste der synagoge, die zeiden: Uw dochter is gestorven, wat valt gij den Meester nog lastig?',
        36: 'Maar toen Jezus het woord gehoord had, dat gesproken was, zeide Hij tot den overste der synagoge: Vrees niet, geloof maar!',
        37: 'En Hij liet aan niemand toe Hem te volgen, dan alleen aan Petrus, en Jakobus en Johannes, den broeder van Jakobus.',
        38: 'En zij kwamen in het huis van den overste der synagoge, en Hij zag het gewoel, en die weenden en zeer klaagden;',
        39: 'en binnengegaan zijnde zeide Hij tot hen: Wat woelt en weent gij toch? het kind is niet gestorven maar slaapt!',
        40: 'En zij lachten Hem uit. Maar Hij joeg hen allen weg, en nam den vader en de moeder van het kind, en die bij Hem waren, en ging binnen waar het kind lag.',
        41: 'En Hij nam de hand des kinds en zeide tot haar: Talitha Kumi! dat wil zeggen: Dochterken, Ik zeg u, sta op!',
        42: 'En terstond rees het dochterken op en wandelde, want het was twaalf jaar oud; en zij waren ten uiterste verwonderd.',
        43: 'En Hij gebood hun scherp dat zij dit aan niemand mochten doen weten, en zeide dat haar wat eten moest gegeven worden.',
    },
    6: {
        1: 'En Jezus ging vandaar weg en kwam naar zijn vaderland, en zijn discipelen volgden Hem.',
        2: 'En toen het sabbat was geworden begon Hij onderwijs te geven in de synagoge. En velen die Hem hoorden stonden verwonderd, zeggende: Vanwaar heeft deze dit alles? en welke wijsheid is het, die Hem gegeven is? en zulke krachten geschieden er door zijn handen?',
        3: 'Is deze niet de timmerman, de zoon van Maria, en de broeder van Jakobus, en van Joses, en van Judas, en van Simon? en zijn ook zijn zusters niet hier bij ons? — En zij werden aan Hem geërgerd.',
        4: 'En Jezus zeide tot hen: Een profeet is niet ongeacht, dan in zijn eigen vaderland, en onder zijn familie, en in zijn huis!',
        5: 'En Hij kon aldaar geen kracht doen, behalve dat Hij aan weinige zieken de handen opleide en ze genas.',
        6: 'En Hij verwonderde zich over hun ongeloof, en trok, onderwijs gevende, door de omliggende dorpen.',
        7: 'En Hij riep de twaalven tot zich, en begon hen uit te zenden twee aan twee, en gaf hun macht over de onzuivere geesten.',
        8: 'En Hij gebood hun dat zij niets zouden meenemen op reis, dan alleen een staf; geen reiszak, geen brood, geen geld in de beurs,',
        9: 'maar met schoenzolen aan de voeten gebonden, en niet bekleed met twee kleederen.',
        10: 'En Hij zeide tot hen: Wanneer gij ergens naar een huis komt, blijft daar totdat gij vandaar weggaat.',
        11: 'En zoo wat plaats u niet zal ontvangen, noch u hooren, schudt, bij het weggaan vandaar, het stof af, dat onder aan uw voeten is, tot een getuigenis tegen hen.',
        12: 'En zij gingen uit en predikten dat zij boetvaardigheid zouden doen;',
        13: 'en veel booze geesten wierpen zij uit, en zalfden veel kranken met olie, en maakten ze gezond.',
        14: 'En de koning Herodes hoorde het, want zijn naam werd vermaard, en zeide: Johannes de Dooper is verrezen uit de dooden, en daarom werken die krachten in Hem!',
        15: 'Anderen nu zeiden: Hij is Elias! En anderen zeiden: Hij is een profeet als een der profeten.',
        16: 'Maar toen Herodes het hoorde zeide hij: Het is Johannes, dien ik onthoofd heb, die uit de dooden is verrezen!',
        17: 'Want deze Herodes had gezonden om Johannes te vangen, en hij had hem in de gevangenis geboeid, ter oorzake van Herodias, de vrouw van Filippus, zijn broeder, omdat hij haar getrouwd had.',
        18: 'Want Johannes zeide tot Herodes: Het is u niet geoorloofd de vrouw uws broeders te hebben!',
        19: 'Herodias nu loerde op hem en wilde hem dooden, en kon niet;',
        20: 'want Herodes vreesde Johannes, wetende dat hij een rechtvaardig en heilig man was; en hij spaarde hem. En als hij hem gehoord had, was hij zeer verslagen en hoorde hem gaarne.',
        21: 'En als er een bekwame dag gekomen was, toen Herodes op zijn kroningsdag een maaltijd had aangericht voor zijn grooten en krijgsoversten, en de eersten van Galilea,',
        22: 'en de dochter van die Herodias binnengekomen was, en danste, behaagde zij aan Herodes en aan degenen die mede aanlagen. En de koning zeide tot het dochterken: Vraag van mij wat gij wilt, en ik zal het u geven!',
        23: 'En hij bezwoer haar: Zoo wat gij van mij vraagt, zal ik u geven, tot de helft van mijn koninkrijk toe!',
        24: 'En zij ging uit en zeide tot haar moeder: Wat zal ik vragen? — En die zeide: Het hoofd van Johannes den Dooper!',
        25: 'En zij ging terstond met haast tot den koning en vroeg, zeggende: Ik wil dat gij mij terstond op een schotel het hoofd geeft van Johannes den Dooper!',
        26: 'En de koning werd zeer bedroefd; doch om de eeden en om de aanliggenden wilde hij haar niet afwijzen.',
        27: 'En de koning zond terstond een van zijn lijfwacht en gebood zijn hoofd te brengen.',
        28: 'Deze nu ging weg en onthoofdde hem in de gevangenis, en hij bracht zijn hoofd op een schotel en gaf het aan het dochterken, en het dochterken gaf het aan haar moeder.',
        29: 'En zijn discipelen hoorden het en kwamen en namen zijn lijk weg en leiden het in een graf.',
        30: 'En de apostelen verzamelden zich tot Jezus en boodschapten Hem al wat zij gedaan en geleerd hadden.',
        31: 'En Hij zeide tot hen: Komt mede, gijlieden alleen, naar een eenzame plaats en rust een weinig! — Want er waren er velen die kwamen en gingen, en zij hadden zelfs geen tijd om te eten.',
        32: 'En zij vertrokken afzonderlijk per schip naar een eenzame plaats.',
        33: 'En de schare zag hen weggaan; en velen kenden hen en liepen over land van alle steden daar samen en kwamen eer dan zij aan.',
        34: 'En Jezus ging uit en zag een groote menigte, en kreeg innerlijk medelijden met hen, omdat ze waren als schapen die geen herder hebben, en Hij begon hun veel te leeren.',
        35: 'En toen het al laat was geworden kwamen zijn discipelen tot Hem en zeiden: Deze plaats is eenzaam, en het is al laat;',
        36: 'zend ze van U, opdat zij naar de omliggende dorpen en vlekken gaan om voor zich zelven wat eten te koopen!',
        37: 'Maar Hij antwoordde en zeide tot hen: Geeft gij hun te eten! — En zij zeiden tot Hem: Wij zouden dan heengaan en voor tweehonderd penningen brood koopen, en hun te eten geven?',
        38: 'En Hij zeide tot hen: Hoeveel brooden hebt gij? gaat heen en ziet! — En toen zij het wisten zeiden zij: Vijf, en twee visschen.',
        39: 'En Hij gebood hun allen bij groepen te gaan zitten op het groene gras.',
        40: 'En zij gingen zitten in groepen van honderd en van vijftig.',
        41: 'En Hij nam de vijf brooden en de twee visschen, en zag op naar den hemel en dankte; en Hij brak de brooden en gaf die aan de discipelen om ze hun voor te zetten, en de twee visschen deelde Hij onder allen.',
        42: 'En zij allen aten en werden verzadigd,',
        43: 'en zij namen twaalf volle korven met brokken op, en ook van de visschen.',
        44: 'En die de brooden gegeten hadden, waren vijf duizend mannen.',
        45: 'En terstond dwong Hij zijn discipelen naar het schip te gaan en vooruit te varen naar den overkant, naar Bethsaïda, terwijl Hij de schare van zich zou laten.',
        46: 'En als Hij van hen afscheid had genomen, ging Hij naar een berg om te bidden.',
        47: 'En toen het avond was geworden, was het schip in het midden der zee, en Hij alleen was op het land;',
        48: 'En als Hij zag dat zij veel moeite hadden om voort te roeien— want zij hadden tegenwind— kwam Hij omtrent de vierde nachtwake tot hen, wandelende op de zee, en Hij wilde hen voorbijgaan.',
        49: 'Maar toen zij Hem op de zee zagen wandelen, meenden zij dat het een spooksel was en zij schreeuwden het uit.',
        50: 'Want zij zagen Hem allen en werden ontroerd. Maar Hij sprak terstond met hen en zeide tot, hen: Hebt moed, Ik ben het, vreest niet!',
        51: 'En Hij klom tot hen in het schip en de wind bedaarde; en zij waren in zich zelven bovenmate zeer ontroerd,',
        52: 'want zij hadden niet opgelet bij de brooden, maar hun hart was verhard.',
        53: 'En toen zij waren overgevaren naar het land, kwamen zij naar Gennesaret en leiden daar aan.',
        54: 'En toen zij uit het schip gegaan waren herkenden ze Hem terstond,',
        55: 'en zij liepen dat geheele land rond en begonnen op bedden de kranken om te dragen daar waar zij hoorden dat Hij was;',
        56: 'en overal waar Hij kwam, naar dorpen, of steden, of vlekken, leiden zij de zieken op de markten, en baden Hem dat zij maar den zoom van zijn kleed mochten aanraken; en zoovelen Hem aanraakten, werden genezen.',
    },
    7: {
        1: 'En tot Jezus vergaderden de fariseërs en eenigen van de schriftgeleerden, die van Jerusalem gekomen waren,',
        2: 'en die gezien hadden dat sommigen zijner discipelen met onzuivere, dat is met ongewasschen handen, brood aten.',
        3: 'Want de fariseërs en al de Joden, als zij niet wel de handen gewasschen hebben, dan eten zij niet, omdat ze vasthouden aan de overlevering der ouden;',
        4: 'en als zij van de markt komen, en zich niet gewasschen hebben, dan eten zij niet; en veel andere dingen zijn er waaraan zij bij overlevering vasthouden, als: het wasschen van bekers, en kannen, en koperen vaten, en bedden.',
        5: 'Die fariseërs en schriftgeleerden vroegen Hem dan: Waarom doen uw discipelen niet naar de overlevering der ouden, maar eten brood met ongewasschen handen?',
        6: 'En Hij zeide tot hen: Te recht heeft Jesaja van u, geveinsden! geprofeteerd, gelijk er geschreven is: Dit volk eert Mij met de lippen, maar hun hart is verre van Mij!',
        7: 'doch tevergeefs dienen zij Mij, omdat zij leeringen leeren, die geboden van menschen zijn!',
        8: 'Gij verlaat het gebod Gods en houdt vast aan de overlevering der menschen; het wasschen van kannen en bekers, en veel zulke dingen doet gij.',
        9: 'En Hij zeide tot hen:’t Is wel fraai, Gods gebod te verwerpen, om uw overleveringen te onderhouden!',
        10: 'Want Mozes heeft gezegd: Eer uw vader en uw moeder, en ook: Die van vader of moeder kwaadspreekt, zal den dood sterven.',
        11: 'Maar gij zegt: Als iemand tot vader of moeder zegt: Wat gij van mij zoudt kunnen trekken, dat is korban (een offergifte die ik aan God moet offeren),',
        12: 'en gij laat hem niet meer toe iets aan vader of moeder te doen,',
        13: 'dan maakt gij Gods woord krachteloos door uw overlevering, die gij hebt ingesteld; en soortgelijke dingen doet gij veel!',
        14: 'En Hij riep de menigte wederom tot zich en zeide tot hen: Luistert allen naar Mij, en verstaat!',
        15: 'Niets is er, dat van buiten tot den mensch ingaat, dat hem kan onzuiver maken; maar wat uit den mensch uitgaat, dat is het wat den mensch onzuiver maakt;',
        16: 'als iemand ooren heeft om te hooren, die hoore!',
        17: 'En toen Hij van de schare naar huis gekomen was, vroegen Hem zijn discipelen naar de gelijkenis.',
        18: 'En Hij zeide tot hen: Zijt ook gij zoo onverstandig? Verstaat gij niet dat al wat van buiten tot den mensch ingaat hem niet kan onzuiver maken?',
        19: 'dat dit niet komt tot zijn hart, maar tot zijn buik, en uitgaat in het geheim, zuiverende alle spijzen?',
        20: 'En Hij zeide: Wat uit den mensch uitgaat, dat maakt den mensch onzuiver;',
        21: 'want van binnen, uit het hart der menschen, komen de kwade gedachten voort, overspel, hoererij, moord,',
        22: 'diefstal, hebzucht, slechtheid, list, ontucht, afgunst, lastering, hoovaardij, onverstand.',
        23: 'Al dit kwade komt van binnen, en maakt den mensch onzuiver.',
        24: 'En vandaar opstaande, ging Hij naar de omstreken van Tyrus en Sidon. En in een huis gegaan zijnde wilde Hij niet dat iemand het wist, en toch kon Hij niet verborgen blijven.',
        25: 'Want toen een vrouw van Hem gehoord had, wier dochterken een onzuiveren geest had, kwam zij terstond en viel aan zijn voeten;',
        26: 'de vrouw nu was een grieksche, een syrofenicische van geboorte— en zij smeekte Hem dat Hij den boozen geest uit haar dochter zou werpen.',
        27: 'En Jezus zeide tot haar: Laat eerst de kinderen verzadigd worden; want het is niet schoon het brood van de kinderen te nemen en voor de honden te werpen!',
        28: 'Maar zij antwoordde en zeide tot Hem: ‘t Is waar, Heere! want ook de honden onder de tafel eten van de kruimels der kinderen!',
        29: 'En Hij zeide tot haar: Om dezes woords wil, ga heen! de booze geest is uit uw dochter gegaan!',
        30: 'En zij ging naar haar huis en vond het kind te bed liggen en den boozen geest uitgegaan.',
        31: 'En Jezus wederom uit de omstreken van Tyrus weggegaan zijnde, kwam door Sidon naar de zee van Galilea, midden door de omstreken van Dekapolis.',
        32: 'En zij brachten tot Hem een doove, die moeilijk sprak, en zij baden Hem dat Hij op dezen de hand zou leggen.',
        33: 'En Hij nam hem uit de schare ter zijde, stak hem zijn vingers in de ooren, en gespuwd hebbende, raakte Hij zijn tong aan.',
        34: 'En opziende naar den hemel, zuchtte Hij en zeide tot hem: Effatha! dat is, word geopend!',
        35: 'En zijn ooren werden geopend, en terstond ging de band zijner tong los en hij sprak goed.',
        36: 'En Hij gebood hun dat zij het aan niemand zouden zeggen; maar hoe meer Hij het hun gebood, des te meer vertelden zij het.',
        37: 'En zij waren bovenmate verwonderd, zeggende: Alles heeft Hij goed gedaan, en de dooven doet Hij hooren en de stommen spreken.',
    },
    8: {
        1: 'Toen er nu in die dagen wederom veel volk was, en zij niet te eten hadden, riep Jezus de discipelen samen en zeide tot hen:',
        2: 'Ik heb medelijden met het volk, omdat zij al drie dagen bij Mij zijn gebleven, en zij hebben niet te eten;',
        3: 'en als Ik ze zonder eten naar hun huis laat gaan, zullen zij onderweg bezwijken, en sommigen van hen zijn van verre gekomen!',
        4: 'En zijn discipelen antwoordden Hem: Vanwaar zal iemand; hier in een woestijn, dezen met brood kunnen verzadigen?',
        5: 'En Hij vroeg hun: Hoeveel brooden hebt gij? — En zij zeiden: Zeven.',
        6: 'En Hij gebood het volk op den grond te gaan zitten; en Hij nam de zeven brooden, en dankte, en brak ze, en gaf ze aan zijn discipelen, om ze voor te zetten; en zij zetten ze aan de schare voor.',
        7: 'En zij hadden enkele vischjes; en als Hij gedankt had zette Hij die ook voor.',
        8: 'En zij aten en werden verzadigd, en zij namen het overschot der brokken op, zeven manden.',
        9: 'En die gegeten hadden waren omtrent vier duizend. — En Hij liet ze weggaan.',
        10: 'En terstond ging Hij naar het schip met zijn discipelen en kwam naar de omstreken van Dalmanutha.',
        11: 'En de fariseërs gingen uit en begonnen met Hem te twisten, verzoekende van Hem een teeken uit den hemel, om Hem te verstrikken.',
        12: 'En Hij zuchtte in zijn geest en zeide: Wat verzoekt dit geslacht een teeken? — Voorwaar zeg Ik ulieden: Aan dit geslacht zal geen teeken gegeven worden!',
        13: 'En hen verlatende ging Hij wederom per schip naar de overzijde.',
        14: 'En de discipelen hadden vergeten brooden mede te nemen, en hadden niets dan één brood bij zich in het schip.',
        15: 'En Hij gebood hun, zeggende: Ziet toe, wacht u van den zuurdeesem der fariseërs en van den zuurdeesem van Herodes!',
        16: 'En zij overleiden onder malkander, zeggende: Hij zegt dit omdat wij geen brooden hebben!',
        17: 'En Jezus, dit bemerkt hebbende, zeide tot hen: Wat overlegt gij, dat gij geen brooden hebt? verstaat en begrijpt gij nog niet? hebt gij nog uw verhard harte?',
        18: 'terwijl gij oogen hebt ziet gij niet, en terwijl gij ooren hebt hoort gij niet, en gij hebt geen geheugen?',
        19: 'Toen ik de vijf brooden brak voor de vijf duizend, hoeveel volle korven met brokken naamt gij op? Zij zeiden tot Hem: Twaalf.',
        20: 'En toen Ik de zeven brak voor de vier duizend, hoeveel volle manden met brokken naamt gij toen op? — Zij zeiden: Zeven.',
        21: 'En Hij zeide tot hen: Verstaat gij dan nog niet?',
        22: 'En zij kwamen naar Bethsaïda, en men bracht tot Hem een blinde, en bad Hem dat Hij hem zou aanraken.',
        23: 'En den blinde bij de hand genomen hebbende, bracht Hij hem buiten het dorp. En als Hij hem op de oogen gespuwd had, leide Hij hem de handen op en vroeg hem of hij wat zag.',
        24: 'En opziende zeide de blinde: Ik zie demenschen; want als boomen zie ik ze wandelen!',
        25: 'Toen leide Jezus wederom de handen op zijn oogen en hij zag op en was genezen, en zag alles klaarlijk.',
        26: 'En Hij zond hem naar zijn huis, zeggende: Ga niet naar het dorp en zeg het aan niemand.',
        27: 'En Jezus ging met zijn discipelen uit naar de dorpen van Cesarea Filippi, en onderweg vroeg Hij zijn discipelen en zeide tot hen: Wie zeggen de menschen dat Ik ben?',
        28: 'En zij spraken tot Hem en zeiden: Johannes de Dooper; — en anderen: Elias— en anderen: Een der profeten.',
        29: 'En Hij vroeg hun: Maar gij, wie zegt gij dat Ik ben? En Petrus antwoordde en zeide tot Hem: Gij zijt de Christus!',
        30: 'En Hij gebood hun scherpelijk dat zij tot niemand over Hem spreken zouden.',
        31: 'En Hij begon hun te leeren dat de Zoon des menschen veel moest lijden, en verworpen worden van de oudsten en de overpriesters en de schriftgeleerden, en gedood worden, en na drie dagen verrijzen.',
        32: 'En dit woord sprak Hij vrij uit. En Petrus nam Hem ter zijde en begon Hem te bestraffen.',
        33: 'Maar Hij keerde zich om en op zijn discipelen ziende, bestrafte Hij Petrus en zeide: Ga weg, achter Mij, Satan! want gij bedenkt niet de dingen van God, maar die der menschen!',
        34: 'En als Hij de schare met zijn discipelen tot zich geroepen had, zeide Hij tot hen: Zoo wie wil achter Mij komen die verloochene zich zelven, en neme zijn kruis op, en volge Mij na.',
        35: 'Want zoo wie zijn leven wil behouden, die zal het verliezen, maar zoo wie zijn leven zal verliezen om Mijnentwil en om des Evangelies wil, die zal het behouden.',
        36: 'Want welk profijt zal een mensch hebben, als hij de geheele wereld wint en zijn leven verliest?',
        37: 'Wat toch zal een mensch geven in ruil voor zijn leven?',
        38: 'Want zoo wie zich over Mij en mijn woorden zal geschaamd hebben in dit overspelig en goddeloos geslacht, over dien zal ook de Zoon des menschen zich schamen, als Hij komt in de glorie zijns Vaders met de heilige engelen.',
    },
    9: {
        1: 'En Hij zeide tot hen: Voorwaar, Ik zeg ulieden dat er sommigen hier staan die den dood in ‘t geheel niet smaken zullen, totdat zij het koninkrijk Gods met kracht zullen hebben zien komen!',
        2: 'En zes dagen daarna nam Jezus met zich Petrus, en Jakobus, en Johannes, en bracht hen alleen naar een hoogen berg, afzonderlijk; en Hij werd van gedaante veranderd in hun tegenwoordigheid.',
        3: 'En zijn kleederen werden blinkend, zeer wit, als sneeuw, zooals geen voller op de aarde ze wit kan maken.',
        4: 'En hun verscheen Elias met Mozes, en zij spraken samen met Jezus.',
        5: 'En Petrus antwoordde en zeide tot Jezus: Meester, het is goed dat wij hier zijn, en laat ons drie tenten maken, voor U een, en voor Mozes een, en voor Elias een!',
        6: 'Want hij wist niet wat te antwoorden, want ze waren verschrikt.',
        7: 'En er kwam een wolk die hen overschaduwde, en er kwam een stem uit de wolk: Deze is mijn Zoon, de Beminde, hoort Hem!',
        8: 'En haastig rondziende zagen zij niemand meer; maar Jezus alleen bij zich.',
        9: 'Terwijl zij nu den berg afgingen, gebood Hij hun dat zij aan niemand zouden vertellen wat zij gezien hadden, dan wanneer de Zoon des menschen uit de dooden zou verrezen zijn.',
        10: 'En dit woord hielden zij in het geheugen, en vroegen onder malkander: Wat is dat, uit de dooden verrijzen?',
        11: 'En zij vroegen Hem zeggende: Waarom zeggen de fariseërs en de schriftgeleerden dat Elias eerst moet komen?',
        12: 'En Hij zeide tot hen: Elias als hij komt zal wel eerst alles herstellen; en hoe is er geschreven van den Zoon des menschen? — dat Hij veel zal lijden en veracht worden.',
        13: 'Maar Ik zeg ulieden dat Elias al gekomen is, en zij hebben hem gedaan zooals zij wilden, gelijk van hem geschreven is.',
        14: 'En toen Jezus bij de discipelen was gekomen, zag Hij een groote schare rond hen, en schriftgeleerden die met hen twistten.',
        15: 'En de gansche schare, zoodra zij Hem zag, werd verbaasd, en zij liepen naar Hem toe en groetten Hem.',
        16: 'En Hij vroeg hun: Wat twist gij met dezen?',
        17: 'En een uit de schare antwoordde Hem: Meester, ik heb mijn zoon tot U gebracht, die een stommen geest heeft;',
        18: 'en waar deze hem ook aangrijpt daar scheurt hij hem, en hij schuimbekt en knarst op de tanden, en verstijft; en ik heb aan uw discipelen gezegd, dat zij hem zouden uitwerpen, en zij konden niet.',
        19: 'Maar Jezus antwoordde en zeide tot hen: O ongeloovig geslacht, tot wanneer zal Ik bij u zijn? tot wanneer zal Ik u verdragen? — brengt hem tot Mij!',
        20: 'En zij brachten hem tot Hem. En Hem ziende smeet de geest hem terstond heen en weer; en op den grond vallende wentelde hij zich al schuimbekkende.',
        21: 'En Jezus vroeg aan zijn vader: Hoe lang is het, dat dit hem overkomen is? En hij zeide: Van zijn kindsheid af!',
        22: 'en dikwijls heeft hij hem ook in vuur geworpen en in water, om hem te dooden; maar als Gij iets kunt, ontferm U over ons en help ons!',
        23: 'Maar Jezus zeide tot hem: Wat? zoo Gij kunt? alles is mogelijk voor wie gelooft!',
        24: 'En terstond riep de vader van het kind met tranen uit, zeggende: Ik geloof! help mij, ofschoon in ongeloof!',
        25: 'En toen Jezus zag dat de schare bijeen liep, bestrafte Hij den onzuiveren geest en zeide tot hem: Gij stomme en doove geest, Ik beveel u, ga uit hem en kom niet meer in hem!',
        26: 'En al schreeuwend, en hem heen en weer smijtende, ging hij uit. En het kind werd als een doode, zoodat velen zeiden dat het dood was.',
        27: 'Maar Jezus greep zijn hand en richtte hem op, en hij stond recht.',
        28: 'En toen zij in huis gekomen waren, vroegen zijn discipelen Hem in het bijzonder: Waarom hebben wij hem niet kunnen uitwerpen?',
        29: 'En Hij zeide tot hen: Dit geslacht kan door niets uitgaan, dan door gebed en vasten.',
        30: 'En zij gingen vandaar weg en trokken door Galilea, en Hij wilde niet dat iemand het wist;',
        31: 'want Hij onderwees zijn discipelen en zeide tot hen: De Zoon des menschen wordt overgeleverd in de handen der menschen, en zij zullen Hem dooden, en gedood zijnde zal Hij na drie dagen verrijzen.',
        32: 'Maar zij verstonden de rede niet en zij vreesden Hem er naar te vragen.',
        33: 'En zij kwamen naar Kapernaüm. En toen Hij te huis was, vroeg Hij hun: Waarover hebt gij onderweg gehandeld?',
        34: 'Maar zij zwegen stil, want zij hadden onderweg getwist met malkander, wie toch de meeste was.',
        35: 'En toen Hij nederzat riep Hij de twaalven en zeide tot hen: Als iemand wil de eerste zijn, die zal de laatste van allen zijn, en de dienaar van allen.',
        36: 'En Hij nam een klein kind en stelde dat in hun midden, en omhelsde het en zeide tot hen:',
        37: 'Zoo wie één van zulke kinderen zal aannemen in mijn Naam, die neemt Mij aan; en zoo wie Mij aanneemt, die neemt niet Mij aan, maar Hem die Mij gezonden heeft.',
        38: 'Johannes sprak tot Hem: Meester, wij hebben iemand gezien die in uw Naam booze geesten uitwerpt, en die ons niet volgt; en wij hebben het hem verboden.',
        39: 'Maar Jezus zeide: Verbiedt hem niet! Niemand toch is er die een kracht zal doen in mijn Naam en spoedig van Mij zal kunnen kwaadspreken;',
        40: 'want die niet tegen ons is, is vóór ons!',
        41: 'Want zoo wie ulieden een beker waters te drinken geeft in mijn Naam, omdat gij van Christus zijt, voorwaar Ik zeg ulieden, dat hij zijn loon geenszins zal verliezen.',
        42: 'En zoo wie één dezer kleinen, die in Mij gelooven, ergeren zal, het ware voor hem beter dat er een molensteen om zijn hals was gedaan, en hij in de zee geworpen was.',
        43: 'En als uw hand u ergert, snijd ze af! het is beter dat gij verminkt naar het leven gaat, dan dat gij, twee handen hebbende, naar de helle gaat, naar het onuitbluschbaar vuur,',
        44: 'waar hun worm niet sterft en het vuur niet wordt uitgebluscht.',
        45: 'En als uw voet u ergert, snijd hem af! beter is het dat gij kreupel tot het leven ingaat, dan dat gij, twee voeten hebbende, in de helle geworpen wordt,',
        46: 'het onuitbluschbaar vuur, waar hun worm niet sterft, en het vuur niet wordt uitgebluscht.',
        47: 'En als uw oog u ergert, trek het uit! beter is het dat gij met één oog in het koninkrijk Gods ingaat, dan dat gij, twee oogen hebbende, in de helle geworpen wordt,',
        48: 'waar hun worm niet sterft, en het vuur niet wordt uitgebluscht.',
        49: 'Want ieder zal met vuur gezouten worden, en elk offer zal met zout gezouten worden.',
        50: 'Het zout is goed; maar als het zout onzout wordt, waarmede zult gij het smakelijk maken? — Hebt in u zelven zout en houdt vrede onder malkander!',
    },
    10: {
        1: 'En Jezus stond op en ging vandaar naar de landstreken van Judea en over den Jordaan; en wederom kwamen er scharen tot Hem, en Hij onderwees hen wederom, zooals Hij gewoon was.',
        2: 'En de fariseërs kwamen tot Hem en vroegen Hem of het een man geoorloofd is zijn vrouw te verlaten, — Hem verzoekende.',
        3: 'Maar Hij antwoordde en zeide tot hen: Wat heeft Mozes u geboden?',
        4: 'En zij zeiden: Mozes heeft toegestaan een akte van scheiding te schrijven en haar te verlaten.',
        5: 'Maar Jezus zeide tot hen: Om uw verhardheid van harte heeft hij voor ulieden dit gebod geschreven;',
        6: 'maar van het begin der schepping af heeft God hen man en vrouw gemaakt.',
        7: 'Daarom zal een mensch zijn vader en zijn moeder verlaten, en zijn vrouw aanhangen,',
        8: 'en die twee zullen zijn tot één vleesch, zoodat zij niet meer twee zijn, maar één vleesch.',
        9: 'Wat God dan heeft vereenigd, dat scheide de mensch niet!',
        10: 'En tehuis vroegen de discipelen Hem wederom over deze zaak;',
        11: 'en Hij zeide tot hen: Zoo wie zijn vrouw zal verlaten en met een andere trouwen, doet overspel tegen haar;',
        12: 'en als een vrouw haar man verlaat en met een ander trouwt, doet zij overspel.',
        13: 'En zij brachten kinderkens tot Hem opdat Hij die zou aanraken; maar de discipelen bestraften degenen die ze bij Hem brachten.',
        14: 'En Jezus dit ziende nam het kwalijk en zeide tot hen: Laat de kinderkens tot Mij komen, verhindert ze niet! want voor zoodanigen is het koninkrijk Gods.',
        15: 'Voorwaar Ik zeg ulieden: Zoo wie het koninkrijk Gods niet zal aannemen als een kindeken, die zal er geenszins in komen!',
        16: 'En Hij omhelsde ze en leide hun de handen op, en zegende ze.',
        17: 'En toen Hij op weg ging, liep er een naar Hem toe en voor Hem op de knieën vallende vroeg hij Hem: Goede Meester! wat zal ik doen om eeuwig leven te verkrijgen?',
        18: 'Doch Jezus zeide tot hem: Wat noemt gij Mij goed? niemand is goed dan de eenige God!',
        19: 'De geboden kent gij: Gij zult geen overspel doen, gij zult niet doodslaan, gij zult niet stelen, gij zult geen valsch getuigenis geven, gij zult niemand te kort doen, eer uw vader en uw moeder.',
        20: 'Maar hij zeide tot Hem: Meester, dit alles heb ik onderhouden van mijn jeugd af.',
        21: 'En Jezus zag hem aan en beminde hem, en zeide tot hem: Eén zaak ontbreekt u! ga heen, verkoop al wat gij hebt en geef het aan de armen, en gij zult een schat hebben in den hemel, en kom, en volg Mij!',
        22: 'Maar hij werd bedroefd over dat woord en ging treurig heen, want hij bezat veel goederen.',
        23: 'En Jezus zag rond en zeide tot zijn discipelen: Hoe bezwaarlijk zullen zij die goederen bezitten, tot het koninkrijk Gods ingaan!',
        24: 'En de discipelen werden verwonderd over zijn woorden. Maar Jezus antwoordde wederom en zeide tot hen: Kinderen! hoe bezwaarlijk is het voor hen die op hun goederen vertrouwen, tot het koninkrijk Gods in te gaan!',
        25: 'Gemakkelijker is het dat een kameel door het oog van de naald gaat, dan dat een rijke tot het koninkrijk Gods ingaat!',
        26: 'Zij nu werden nog meer verwonderd en zeiden tot malkander: En wie kan dan behouden worden?',
        27: 'Doch Jezus zag hen aan en zeide: Bij de menschen onmogelijk, maar niet bij God! want bij God is alles mogelijk.',
        28: 'Toen begon Petrus tot Hem te zeggen: Zie, wij hebben alles verlaten en zijn U gevolgd!',
        29: 'Jezus zeide: Voorwaar Ik zeg ulieden, niemand is er, die verlaten heeft huis, of broeders, of zusters, of moeder, of vader, of kinderen, of akkers, om Mijnentwil en om des Evangelies wil,',
        30: 'of hij ontvangt honderdvoudig nu in dezen tijd huizen, en broeders, en zusters, en moeders, en kinderen, en akkers, met vervolgingen, en in de eeuw die komende is, eeuwig leven.',
        31: 'Doch veel eersten zullen laatsten zijn, en de laatsten eersten.',
        32: 'En zij waren op weg om naar Jerusalem te gaan, en Jezus ging vóór hen uit. En zij waren verbaasd, en volgden Hem vreezende. En de twaalven wederom tot zich nemende, begon Hij tot hen te spreken over de dingen die Hem overkomen zouden:',
        33: 'Ziet, wij gaan op naar Jerusalem, en de Zoon des menschen wordt overgeleverd aan de overpriesters en aan de schriftgeleerden, en zij zullen Hem ter dood veroordeelen, en Hem aan de heidenen overleveren,',
        34: 'en zij zullen Hem bespotten, en Hem geeselen, en Hem bespuwen, en Hem dooden, en na drie dagen zal Hij verrijzen.',
        35: 'En tot Hem kwamen Jakobus en Johannes, de zonen van Zebedeüs, en zeiden tot Hem: Meester! wij wenschen dat Gij ons doen zult wat wij U verzoeken!',
        36: 'En Hij zeide tot hen: Wat wilt gij dat Ik u doen zal?',
        37: 'En zij zeiden tot Hem: Geef ons dat wij, de een aan uw rechter– en de ander aan uw linkerhand, mogen zitten in uw glorie!',
        38: 'Maar Jezus zeide tot hen: Gij weet niet wat gij begeert! Kunt gij drinken den drinkbeker dien Ik drink, of gedoopt worden met den doop waarmede Ik gedoopt word?',
        39: 'En zij zeiden tot Hem: Ja wel! — En Jezus zeide tot hen: Den drinkbeker, dien Ik drink, zult gij drinken, en met den doop, waarmede Ik gedoopt word, zult gij gedoopt worden!',
        40: 'doch het zitten aan mijn rechter– of aan mijn linkerhand staat bij Mij niet te geven, maar is voor wie het bereid is.',
        41: 'En toen de tien andere aposlelen dit gehoord hadden begonnen zij het kwalijk te nemen van Jakobus en Johannes.',
        42: 'En Jezus riep hen tot zich en zeide tot hen: Gij weet dat degenen die geacht worden oversten der volken te zijn over hen heerschen, en hun grooten hebben macht over hen;',
        43: 'doch niet alzoo is het onder u, maar zoo wie wil groot worden onder u, zal uw dienaar zijn;',
        44: 'en zoo wie van u de eerste wil worden, zal een knecht van allen zijn;',
        45: 'want ook de Zoon des menschen is niet gekomen om gediend te worden, maar om te dienen en zijn leven te geven tot een losprijs voor velen.',
        46: 'En zij kwamen naar Jericho. En als Hij Jericho uitging met zijn discipelen en een groote menigte volks, zat Bartimeüs, een blinde bedelaar, zoon van Timeüs, aan den weg.',
        47: 'En toen hij gehoord had dat het Jezus de Nazarener was, begon hij te roepen en te zeggen: Zone Davids! Jezus! ontferm U mijner!',
        48: 'En velen bestraften hem, opdat hij zou zwijgen; maar des te meer riep hij: Zone Davids! ontferm U mijner!',
        49: 'En Jezus bleef staan en zeide: Roept hem! En zij riepen den blinde en zeiden tot hem: Heb moed, sta op, Hij roept u!',
        50: 'En hij wierp zijn mantel af, en sprong op en kwam tot Jezus.',
        51: 'En Jezus antwoordde en zeide tot hem: Wat wilt gij dat Ik u doen zal? — En de blinde zeide tot Hem: Meester, dat ik ziende mag worden!',
        52: 'Jezus zeide tot hem: Ga heen, uw geloof heeft u behouden! — En terstond werd hij ziende, en volgde Hem op den weg.',
    },
    11: {
        1: 'En toen zij nabij Jerusalem kwamen, bij Bethfage en Bethanië, aan den Berg der Olijven, zond Jezus twee zijner discipelen en zeide tot hen:',
        2: 'Gaat heen naar het dorp daar vóór u, en terstond als gij er inkomt, zult gij een veulen vastgebonden vinden, waarop nooit een mensch gezeten heeft; maakt dat los en brengt het.',
        3: 'En als soms iemand tot u zegt: Waarom doet gij dat? dan moet gij zeggen: De Heere heeft het van doen! en terstond zal hij het wederom naar hier zenden.',
        4: 'En zij gingen heen en vonden het veulen vastgebonden bij de deur, buiten aan de open straat, en zij maakten het los:',
        5: 'En sommigen van die daar stonden zeiden tot hen: Wat doet gij, dat gij het veulen losmaakt?',
        6: 'Zij nu zeiden tot hen zooals Jezus gezegd had. En ze lieten hen begaan.',
        7: 'En zij brachten het veulen tot Jezus en wierpen hun kleederen daarover, en zetten Hem daarop.',
        8: 'En velen spreidden hun kleederen op den weg, en anderen takken, die ze van de velden afsneden.',
        9: 'En die vooraan gingen en die volgden riepen: Hosannah, gezegend Hij die komt in den Naam des Heeren!',
        10: 'Gezegend het koninkrijk van onzen vader David, dat komt! Hosannah, in het allerhoogste!',
        11: 'En Jezus kwam naar Jerusalem, naar den tempel; en als Hij alles rondom bezien had en het al avond was geworden, ging Hij uit naar Bethanië met de twaalven.',
        12: 'En toen zij den volgenden dag uit Bethanië gingen, kreeg Hij honger.',
        13: 'En van verre een vijgeboom ziende, die bladeren had, ging Hij er naar toe, of Hij er ook wat aan vinden zou; en er bij gekomen zijnde, vond Hij niets dan bladeren; want het was de tijd der vijgen niet;',
        14: 'en Hij antwoordde en zeide tot den boom: Tot in eeuwigheid ete niemand meer vrucht van u! — En zijn discipelen hoorden het.',
        15: 'En zij kwamen naar Jerusalem, en naar den tempel gegaan zijnde, begon Jezus degenen die in den tempel kochten en verkochten uit te werpen, en de tafels der wisselaars en de zetels der duivenverkoopers keerde Hij om;',
        16: 'en Hij liet niet toe dat iemand eenig vat door den tempel droeg;',
        17: 'en Hij onderwees hen en zeide tot hen: Is er niet geschreven: Mijn huis zal een huis des gebeds genoemd worden voor alle volken? Gij nu hebt het gemaakt tot een roovershol.',
        18: 'En de overpriesters en de schriftgeleerden hoorden dit, en zochten hoe zij Hem zouden dooden. Want zij vreesden Hem, omdat de gansche schare verbaasd stond over zijn onderwijs.',
        19: 'En toen het avond was geworden vertrok Hij uit de stad.',
        20: 'En des morgens vroeg voorbijgaande zagen zij dat de vijgeboom verdord was van de wortelen af.',
        21: 'En Petrus, dit indachtig geworden zijnde, zeide tot Hem: Meester, zie de vijgeboom dien Gij vervloekt hebt, is verdord!',
        22: 'En Jezus antwoordde en zeide tot hen: Hebt geloof in God!',
        23: 'Voorwaar Ik zeg ulieden, zoo wie tot dezen berg zou zeggen: Hef u op en werp u in de zee! en niet twijfelt in zijn hart, maar gelooft dat wat hij zegt geschieden zal, — het zal hem geworden!',
        24: 'Daarom zeg Ik ulieden: al wat gij bidt en begeert, gelooft dat gij het ontvangen zult, en het zal u geworden.',
        25: 'En als gij staat om te bidden, vergeeft het dan als gij iets hebt tegen iemand, opdat ook uw Vader, die in de hemelen is, ulieden uw overtredingen vergeve;',
        26: 'maar als gijlieden niet vergeeft, dan zal ook uw Vader, die in de hemelen is, uw overtredingen niet vergeven.',
        27: 'En zij kwamen wederom naar Jerusalem. En terwijl Jezus in den tempel wandelde kwamen tot Hem de overpriesters, en de schriftgeleerden, en de oudsten,',
        28: 'en zeiden tot Hem: Door welke macht doet Gij deze dingen? of wie heeft U de macht gegeven om deze dingen te doen?',
        29: 'En Jezus zeide tot hen: Ik zal u ook één ding vragen, en antwoordt Mij, dan zal Ik u zeggen door welke macht Ik deze dingen doe.',
        30: 'De doop van Johannes, was die uit den hemel of uit de menschen? — antwoordt Mij!',
        31: 'En zij redeneerden onder malkander zeggende: Als wij zeggen: Uit den hemel, dan zal Hij zeggen: Waarom hebt gij hem dan niet geloofd?',
        32: 'Maar als wij zeggen: Uit de menschen? — Zij vreesden het volk; want allen hielden voor vast, dat Johannes een profeet was.',
        33: 'En zij antwoordden Jezus en zeiden: Wij weten het niet. — En Jezus zeide tot hen: Dan zeg Ik u ook niet door welke macht Ik deze dingen doe.',
    },
    12: {
        1: 'En Jezus begon tot hen in gelijkenissen te spreken: Een mensch plantte een wijngaard, en leide er een haag rond, en groef een wijnpers en bouwde een wachttoren, en verhuurde hem aan landlieden, en reisde buitenslands;',
        2: 'en toen het tijd was, zond hij een dienstknecht tot de landlieden, om van de landlieden te ontvangen van de vruchten des wijngaards.',
        3: 'Doch zij grepen en sloegen hem en zonden hem ledig weg.',
        4: 'En wederom zond hij tot hen een anderen dienstknecht,; en dezen sloegen zij een wonde aan het hoofd en mishandelden hem.',
        5: 'En hij zond wederom een anderen, en dezen doodden zij; en vele anderen, die zij of sloegen, of doodden.',
        6: 'Als hij dan nog één beminden zoon had, zond hij ten laatste dezen tot hen, zeggende: Zij zullen toch mijn zoon ontzien!',
        7: 'Maar die landlieden zeiden tot malkander: Deze is de erfgenaam! komt, laat ons hem dooden, en de erfenis zal voor ons zijn!',
        8: 'En zij grepen en doodden hem, en wierpen hem buiten den wijngaard.',
        9: 'Wat zal dan de heer van den wijngaard doen? — Hij zal komen en de landlieden ombrengen, en den wijngaard aan anderen geven.',
        10: 'Hebt gij ook deze Schrifture niet gelezen: De steen, dien de bouwlieden hebben verworpen, die is geworden tot een hoeksteen;',
        11: 'van den Heer is dit geschied en het is wonder in onze oogen?',
        12: 'En zij zochten Hem te grijpen, en vreesden het volk, want zij verstonden dat Hij de gelijkenis op hen gesproken had; en zij verlieten Hem en gingen weg.',
        13: 'En zij zonden tot Hem eenigen van de fariseërs en van de herodianen, om Hem in zijn woorden te vangen.',
        14: 'En zij kwamen tot Hem en zeiden: Meester, wij weten dat Gij waarachtig zijt, en niemand ontziet, want Gij ziet niet naar het aangezicht der menschen, maar leert den weg Gods naar waarheid. — Is het geoorloofd belasting aan den keizer te geven, of niet?',
        15: 'Hij nu zag hun geveinsdheid en zeide tot hen: Wat verzoekt gij Mij? brengt Mij een penning, dat Ik hem zie.',
        16: 'En zij brachten Hem er een. En Hij zeide tot hen: Van wien is dit beeld en het opschrift? Zij nu zeiden: Van den keizer!',
        17: 'Jezus dan zeide tot hen: Geeft dan aan den keizer wat den keizer, en aan God wat Gode toekomt! — En zij verwonderden zich over Hem.',
        18: 'En er kwamen sadduceërs tot Hem, die zeggen dat er geen verrijzenis is, en zij vroegen Hem, zeggende:',
        19: 'Meester, Mozes heeft ons voorgeschreven dat, als iemands broeder sterft en deze een vrouw, maar geen kind nalaat, dat dan zijn broeder de vrouw moet nemen en voor zijn gestorven broeder nakomelingschap verwekken.',
        20: 'Er waren nu zeven broeders; en de eerste nam een vrouw en liet bij zijn sterven geen nakomelingschap na;',
        21: 'en de tweede broeder nam haar en liet bij zijn sterven geen nakomelingschap na; en de derde evenzoo;',
        22: 'en al de zeven namen haar en lieten geen nakomelingschap na; ten laatste van allen is ook de vrouw gestorven.',
        23: 'In de verrijzenis nu, als zij zullen verrezen zijn, van wien zal zij dan de vrouw zijn? want de zeven hebben haar tot vrouw gehad.',
        24: 'Doch Jezus zeide tot hen: Dwaalt gij niet daarom, dat gij de Schrifturen niet kent, noch de kracht Gods?',
        25: 'Want wanneer zij uit de dooden verrijzen, zullen zij niet trouwen of getrouwd worden, maar zij zijn als engelen in de hemelen.',
        26: 'Aangaande de dooden nu, dat zij verrijzen zullen, hebt gij niet gelezen in het boek van Mozes, hoe God bij den braambosch tot hem sprak, zeggende: Ik ben de God van Abraham, en de God van Isaäk, en de God van Jakob?',
        27: 'Hij is niet de God van dooden, maar van levenden. Gij dwaalt dan zeer!',
        28: 'En een der schriftgeleerden, die hen had hooren redetwisten, kwam tot Hem, en wetende dat Hij hun goed had geantwoord, vroeg hij Hem: Wat is het eerste gebod van allen?',
        29: 'Jezus antwoordde: Het eerste is: Hoor Israël, de Heere, onze God, is een éénig Heer!',
        30: 'en gij zult den Heere, uwen God, beminnen uit geheel uw hart, en uit geheel uw ziel, en uit geheel uw verstand, en uit geheel uw kracht;',
        31: 'het tweede gebod is dit: Gij zult uw naaste beminnen als u zelven, Daar is geen ander gebod, grooter dan deze.',
        32: 'En de schriftgeleerde zeide tot Hem: Juist, Meester! in waarheid hebt Gij gezegd dat er maar één God is, en dat er geen andere is dan Hij;',
        33: 'en Hem te beminnen uit het geheele hart, en uit het geheele verstand, en uit geheel de ziel, en uit de geheele kracht, en den naaste te beminnen als zich zelven, is meer dan al de brandoffers en slachtoffers!',
        34: 'En Jezus zag dat hij verstandig had geantwoord en zeide tot hem: Niet ver zijt gij van het koninkrijk Gods! — En niemand durfde Hem meer vragen.',
        35: 'En Jezus antwoordde en zeide, toen Hij onderwijs gaf in den tempel: Hoe zeggen de schriftgeleerden dat de Christus Davids Zoon is?',
        36: 'David zelf toch heeft gezegd in den Heiligen Geest: De Heere heeft tot mijn Heere gesproken: Zit aan mijn rechterhand totdat Ik uw vijanden gezet heb tot een voetbank uwer voeten?',
        37: 'David zelf noemt Hem Heere, en vanwaar is Hij dan zijn Zoon? — En de geheele schare hoorde Hem gaarne.',
        38: 'En in zijn onderwijs zeide Hij: Wacht u voor de schriftgeleerden, die gaarne in lange kleederen wandelen en op de markten gegroet worden,',
        39: 'en vooraanzitten in de synagogen en vooraanliggen bij de maaltijden;',
        40: 'die de huizen der weduwen opeten en voor den schijn lange gebeden doen; dezen zullen een zwaarder oordeel ontvangen.',
        41: 'En Hij ging zitten tegenover de schatkist en zag hoe de schare geld wierp in de schatkist; en vele rijken wierpen er veel in.',
        42: 'En er kwam één arme weduwe, die twee penningskens er inwierp, dat is een kodrant.',
        43: 'En Hij riep zijn discipelen en zeide tot hen: Voorwaar, Ik zeg u dat deze arme weduwe er meer heeft ingeworpen dan allen die in de schatkist geld geworpen hebben;',
        44: 'want allen hebben er ingeworpen van hun overvloed, maar deze heeft van haar armoede, al wat zij had, er ingeworpen, haar geheelen schat.',
    },
    13: {
        1: 'En toen Jezus uit den tempel ging zeide een zijner discipelen tot Hem: Meester, zie eens, hoedanige steenen en hoedanige gebouwen!',
        2: 'En Jezus zeide tot hem: Gij ziet die groote gebouwen? — geen twee steenen zullen op elkander gelaten worden, die niet zullen afgebroken worden!',
        3: 'En toen Hij op den Berg der Olijven zat, tegenover den tempel, vroegen Petrus, en Jakobus, en Johannes, en Andreas Hem afzonderlijk:',
        4: 'Zeg ons, wanneer zal dat zijn? en wat is het teeken, als dit alles zal volbracht worden?',
        5: 'En Jezus begon tot hen te zeggen: Ziet toe, dat u niemand verleide!',
        6: 'Velen zullen komen onder mijn Naam, zeggende: Ik ben het! en zij zullen velen verleiden.',
        7: 'Als gij dan hooren zult van oorlogen en oorlogsgeruchten, verschrikt niet! want dit moet geschieden, maar nog is het einde er niet.',
        8: 'Want volk zal tegen volk opstaan, en koninkrijk tegen koninkrijk; aardbevingen zullen er allerwege zijn, en hongersnooden! — Dat is het begin der smarten.',
        9: 'Maar ziet gij toe voor u zelven; want zij zullen u overleveren aan de raadsvergaderingen, en in de synagogen zult gij geslagen worden, en voor stadhouders en koningen zult gij gesteld worden om Mijnentwille, tot een getuigenis voor hen.',
        10: 'En aan al de volken moet eerst het Evangelie gepredikt worden.',
        11: 'En als zij u wegvoeren en overleveren, weest dan te voren niet bekommerd wat gij zeggen zult, maar wat u zal worden gegeven in die ure, spreekt dat; want gij zijt het niet die spreekt, maar de Heilige Geest.',
        12: 'En de eene broeder zal den anderen broeder overgeven tot den dood, en een vader zijn kind, en kinderen zullen opstaan tegen ouders en zullen hen dooden;',
        13: 'en gij zult gehaat zijn door allen om mijns Naams wil; maar die zal volharden tot den einde, die zal behouden worden.',
        14: 'Wanneer gij dan den gruwel der verwoesting zult zien staan waar hij niet mag zijn—(die het leest lette er op! — dat dan die in Judea zijn naar de bergen vluchten;',
        15: 'die dan op het dak is, kome niet naar beneden in zijn huis, en ga niet uit om iets uit zijn huis weg te nemen;',
        16: 'en die op den akker is, keere niet terug om zijn kleed weg te nemen!',
        17: 'Maar wee den zwangeren en den zogenden in die dagen!',
        18: 'Bidt dus, dat dit niet voorvalle in den winter!',
        19: 'Want in die dagen zal er een verdrukking zijn, zooals er geene is geweest van het begin der schepping, die God geschapen heeft, tot nu toe, en ook niet zijn zal.',
        20: 'En zoo de Heere die dagen niet verkort had, geen vleesch zou behouden worden; maar ter wille van de uitverkorenen, die Hij uitverkoren heeft, heeft Hij die dagen verkort.',
        21: 'En als iemand dan tot ulieden zal zeggen: Zie hier, de Christus! — zie daar! — gelooft het niet.',
        22: 'Want schijnchristussen en schijnprofeten zullen er opstaan, en zij zullen mirakelen doen en teekenen om te verleiden, als het mogelijk was, zelfs de uitverkorenen.',
        23: 'Maar ziet gijlieden toe; Ik heb u alles voorzegd!',
        24: 'Maar in die dagen, na die verdrukking, zal de zon duister worden, en de maan zal haar licht niet geven,',
        25: 'en de sterren zullen uit den hemel vallen, en de krachten, die in de hemelen zijn, zullen beroerd worden;',
        26: 'en alsdan zullen zij den Zoon des menschen zien komen in wolken, met veel kracht en glorie;',
        27: 'en alsdan zal Hij de engelen zenden en zal de uitverkorenen verzamelen uit de vier windstreken, van het uiteinde der aarde tot het uiteinde des hemels.',
        28: 'Van den vijgeboom nu leert gij deze gelijkenis: Zoodra zijn tak zacht wordt en de bladeren uitbotten, dan weet gij dat de zomer nabij is.',
        29: 'Zoo ook gijlieden, als gij die dingen ziet geschieden, dan weet gij dat het nabij is, vóór de deur.',
        30: 'Voorwaar, Ik zeg ulieden, dat deze natie niet zal voorbijgaan, totdat dit alles zal geschied zijn.',
        31: 'De hemel en de aarde zullen voorbijgaan, maar mijn woorden zullen geenszins voorbijgaan!',
        32: 'Maar van dien dag of die ure weet niemand, noch de engelen in den hemel, noch de Zoon, maar wel de Vader.',
        33: 'Ziet toe, zijt gereed en bidt! want gij weet niet wanneer het de tijd is.',
        34: 'Het is zooals een mensch, die buitenslands ging, zijn huis verliet en zijn dienstknechten het bestuur gaf, aan een ieder zijn werk, en aan den deurwachter gebood dat hij waken zou.',
        35: 'Waakt dan, want gij weet niet wanneer de heer des huizes komt, of laat, of des middernachts, of tegen den morgen, of des morgens vroeg!',
        36: 'opdat hij, onverziens komende, u niet slapende vinde.',
        37: 'En wat Ik ulieden zeg, dat zeg Ik tot allen: — Waakt!',
    },
    14: {
        1: 'En het feest van Paschen en van de ongedeesemde brooden was na twee dagen; en de overpriesters en de schriftgeleerden zochten hoe zij Hem met list zouden vatten en dooden.',
        2: 'Want zij zeiden: Niet op het feest, opdat er geen volksoproer geschiede.',
        3: 'En als Hij in Bethanië was, in het huis van Simon den melaatsche, terwijl Hij aanlag, kwam er een vrouw die een albasten flesch had met onvervalschten, kostbaren nardusbalsem; en zij brak de albasten flesch en goot die uit over zijn hoofd.',
        4: 'Sommigen nu waren er die dit bij zich zelven kwalijk namen, en zeiden: Waartoe dient dit verlies van den balsem?',
        5: 'Want deze balsem had kunnen verkocht worden voor meer dan driehonderd penningen, en den armen gegeven zijn! — En zij werden vergramd tegen haar.',
        6: 'Maar Jezus zeide: Laat haar doen; waarom doet gij haar moeite aan? een goed werk heeft zij aan Mij gedaan;',
        7: 'Want de armen hebt gij altijd met u, en als gij wilt kunt gij hun goed doen, maar Mij hebt gij niet altijd;',
        8: 'zij heeft gedaan wat ze kon; zij is mijn lichaam vooraf reeds komen zalven ter begrafenis.',
        9: 'Voorwaar Ik zeg ulieden: Overal waar het Evangelie zal worden gepredikt, over de geheele wereld, daar zal ook gesproken worden tot haar gedachtenis van hetgeen zij heeft gedaan.',
        10: 'En Judas Iskariot, een van de twaalven, ging heen tot de overpriesters, om Jezus aan hen over te leveren.',
        11: 'Dezen nu waren verblijd toen zij dit hoorden en beloofden hem geld te geven; en hij zocht hoe hij Hem ter rechtertijd zou overleveren.',
        12: 'En op den eersten dag der ongedeesemde brooden, als men het paaschlam slachtte, zeiden zijn discipelen tot Jezus: Waar wilt Gij dat wij den paaschmaaltijd gaan toebereiden om dien te eten?',
        13: 'En Hij zond twee zijner discipelen uit en zeide tot hen: Gaat heen naar de stad Jerusalem, en u zal een mensch ontmoeten die een kruik water draagt; volgt hem.',
        14: 'En waar hij ingaat, zegt daar tot den huisheer: De Meester zegt: Waar is mijn eetplaats, waar Ik het paaschmaal met mijn discipelen zal eten?',
        15: 'En hij zal u een groote bovenzaal wijzen, toebereid en gereed; en daar zult gij het ons bereiden.',
        16: 'En de discipelen gingen uit en gingen naar de stad, en vonden het zooals Hij hun gezegd had, en zij bereidden het paaschmaal.',
        17: 'En toen het avond was geworden kwam Hij met de twaalven.',
        18: 'En toen zij aanlagen en aten zeide Jezus: Voorwaar, Ik zeg ulieden dat één uit ulieden, die met Mij eet, Mij verraden zal.',
        19: 'En zij begonnen bedroefd te worden en één voor één tot Hem te zeggen: Ik toch niet?',
        20: 'En Hij zeide tot hen: Eén uit de twaalven, die met Mij in den schotel indoopt;',
        21: 'de Zoon des menschen gaat wel heen, zooals van Hem is geschreven; maar wee dien mensch, door wien de Zoon des menschen wordt verraden! Het ware hem goed als die mensch niet geboren was!',
        22: 'En toen zij aan het eten waren nam Jezus brood, en Hij dankte, en brak het, en gaf het hun, en zeide: Neemt, dat is mijn lichaam!',
        23: 'En den beker nemende, en een dankzegging gesproken hebbende, gaf Hij hun dien, en zij dronken allen daaruit.',
        24: 'En Hij zeide tot hen: Dit is mijn bloed des nieuwen verbonds, dat voor velen wordt vergoten!',
        25: 'Voorwaar, Ik zeg ulieden dat Ik geenszins meer drinken zal van de vrucht des wijnstoks, tot op dien dag, als Ik ze nieuw zal drinken in het koninkrijk Gods.',
        26: 'En als zij den lofzang hadden gezongen gingen zij uit naar den Berg der Olijven.',
        27: 'En Jezus zeide tot hen: Gij allen zult dezen nacht aan Mij geërgerd worden, want er is geschreven: Ik zal den Herder slaan, en de schapen zullen verstrooid worden.',
        28: 'Maar nadat Ik zal verrezen zijn, zal Ik u voorgaan naar Galilea.',
        29: 'Petrus nu zeide tot Hem: Al zouden zij ook allen geërgerd worden, ik toch niet!',
        30: 'En Jezus zeide tot hem: Voorwaar, Ik zeg u dat gij heden, in dezen nacht, eer dat een haan tweemaal zal gekraaid hebben, Mij driemaal zult verloochenen!',
        31: 'Maar Petrus zeide nog te meer: Al móest ik ook met U sterven, ik zal U geenszins verloochenen! — Desgelijks spraken zij ook allen.',
        32: 'En zij kwamen aan een plaats, genaamd Gethsemane, en Hij zeide tot zijn discipelen: Zit hier neder, totdat Ik gebeden heb.',
        33: 'En Hij nam Petrus en Jakobus en Johannes met zich mede, en begon ontroerd en benauwd te worden,',
        34: 'en zeide tot hen: Mijn ziel is diep bedroefd tot stervens toe; blijft hier en waakt!',
        35: 'En een weinig voortgaande viel Hij op den grond, en bad dat die ure van Hem mocht voorbijgaan, als het mogelijk was.',
        36: 'En Hij zeide: Abba, Vader! alles is U mogelijk; neem van Mij dezen drinkbeker weg! — Doch niet wat Ik wil, maar wat Gij wilt!',
        37: 'En Hij kwam en vond hen slapende, en Hij zeide tot Petrus: Simon, gij slaapt? — kunt gij niet één ure waken?',
        38: 'Waakt en bidt, opdat gij niet tot bekoring komt: De geest is wel gewillig, maar het vleesch is zwak.',
        39: 'En wederom ging Hij heen en bad, en sprak dezelfde woorden.',
        40: 'En terugkeerende vond Hij hen wederom slapende, want hun oogen waren bezwaard, en zij wisten niet wat zij Hem zouden antwoorden.',
        41: 'En Hij kwam voor de derde maal en zeide tot hen: Slaapt nu voort en rust! Het is genoeg. De ure is gekomen; ziet, de Zoon des menschen wordt overgeleverd in de handen der zondaren!',
        42: 'Staat op, laat ons gaan! Ziet, die Mij verraadt is nabij!',
        43: 'En terstond, toen Hij nog sprak, kwam Judas Iskariot, één van de twaalven, en met hem een groote menigte, met zwaarden en stokken, van de overpriesters en de schriftgeleerden, en de oudsten.',
        44: 'De verrader nu had hun een teeken gegeven, zeggende: Dien ik zal kussen, die is het; grijpt Hem en voert Hem zeker weg!',
        45: 'En toen hij er gekomen was, ging hij terstond op Hem toe en zeide: Meester! — En hij kuste Hem.',
        46: 'En zij sloegen de handen aan Hem en grepen Hem.',
        47: 'En één dergenen die er bij stonden trok het zwaard en trof des hoogepriesters dienstknecht en sloeg hem het oor af.',
        48: 'En Jezus antwoordde en zeide tot hen: Als tegen een roover zijt gij uitgegaan, met zwaarden en stokken, om Mij te vangen?',
        49: 'dagelijks was Ik bij ulieden in den tempel en leerde, en gij hebt Mij niet gegrepen! Maar zoo moeten de schrifturen vervuld worden.',
        50: 'En ze verlieten Hem allen en vluchtten weg.',
        51: 'En een zeker jongeling volgde Hem, met een linnen kleed om het naakte lichaam, en zij grepen hem;',
        52: 'maar hij liet het kleed in den steek en vluchtte naakt.',
        53: 'En zij voerden Jezus naar den hoogepriester, en al de overpriesters en de oudsten en de schriftgeleerden vergaderden met hem.',
        54: 'En Petrus volgde Hem van verre tot binnen in den voorhof des hoogepriesters, en hij was mede gezeten niet de dienaren en warmde zich, bij het licht van het vuur.',
        55: 'De overpriesters nu en de geheele Raad zochten getuigenis tegen Jezus, om Hem te dooden, en zij vonden er geen.',
        56: 'Want velen gaven een valsch getuigenis tegen Hem en de getuigenissen kwamen niet overeen.',
        57: 'En sommigen stonden op, die valschelijk tegen Hem getuigden, zeggende:',
        58: 'Wij hebben Hem hooren zeggen: Ik zal dezen tempel, die met handen gemaakt is, afbreken, en in drie dagen een anderen bouwen, zonder handen gemaakt.',
        59: 'Doch ook alzoo kwam hun getuigenis niet overeen.',
        60: 'En de hoogepriester stond op in het midden en vroeg Jezus, zeggende: Antwoordt Gij niets? wat getuigen dezen tegen U?',
        61: 'Maar Hij zweeg en antwoordde niets. — Wederom vroeg de hoogepriester Hem en zeide tot Hem: Gij zijt de Christus, de Zoon van den Hooggeloofde?',
        62: 'En Jezus zeide: Ik ben het! en gij zult den Zoon des menschen zien, gezeten aan de rechterhand der Almacht, en komende met de wolken des hemels!',
        63: 'En de hoogepriester scheurde zijn kleederen en zeide: Wat hebben we nog getuigen van noode?',
        64: 'gij hebt de lastering gehoord! Wat dunkt ulieden? En zij allen veroordeelden Hem des doods schuldig te zijn.',
        65: 'En sommigen begonnen Hem te bespuwen en Hem het aangezicht te bedekken, en Hem met vuisten te slaan, en zeiden tot Hem: Profeteer! — En de dienaren sloegen Hem in het gezicht.',
        66: 'En toen Petrus beneden in den voorhof was kwam een der dienstmaagden des hoogepriesters.',
        67: 'En Petrus ziende, die zich warmde, zag zij hem aan en zeide: Ook gij waart met den Nazarener Jezus!',
        68: 'Maar hij loochende het en zeide: Ik weet en versta niet wat gij zegt! — En hij ging naar buiten, naar het voorportaal en een haan kraaide.',
        69: 'En de dienstmaagd hem ziende, begon wederom te zeggen tot die daarbij stonden: Deze is een uit hen!',
        70: 'Maar hij loochende het wederom. En kort daarna zeiden degenen die daarbij stonden wederom tot Petrus: Waarlijk, gij zijt een uit hen, want gij zijt ook een Galileër!',
        71: 'Maar hij begon te vloeken en te zweren: Ik ken dien mensch niet, van wien gij spreekt!',
        72: 'En terstond kraaide een haan voor de tweede maal. En Petrus werd het woord indachtig, hoe Jezus tot hem gezegd had: Eer een haan tweemaal zal kraaien, zult gij Mij driemaal verloochenen. — En hij dacht daarover na, en weende.',
    },
    15: {
        1: 'En terstond, des morgens vroeg, hielden de overpriesters, met de oudsten, en de schriftgeleerden, en den geheelen Raad samen een vergadering; en toen zij Jezus gebonden hadden voerden zij Hem weg en gaven Hem over aan Pilatus.',
        2: 'En Pilatus vroeg Hem: Gij zijt de Koning der Joden? — En Jezus antwoordde en zeide tot hem: Gij zegt het.',
        3: 'En de overpriesters beschuldigden Hem van vele dingen.',
        4: 'Maar Pilatus vroeg Hem wederom: Antwoordt Gij niets? zie, van hoeveel beschuldigen zij U!',
        5: 'Maar Jezus antwoordde niets meer, zoodat Pilatus zich verwonderde.',
        6: 'En op het feest liet hij hun één gevangene los, dien zij begeerden.',
        7: 'Er was nu een, Barabbas genoemd, met de oproermakers gevangen, die in een oproer een moord had begaan.',
        8: 'En de schare kwam op en begon te eischen dat hij hun doen zou, zooals hij gewoon was.',
        9: 'Doch Pilatus antwoordde en zeide tot hen: Wilt gij dat ik u den koning der Joden zal loslaten?',
        10: 'Want hij wist dat de overpriesters Hem uit nijdigheid hadden overgeleverd.',
        11: 'Doch de overpriesters stookten de schare op, dat hij hun Barabbas liever zou loslaten.',
        12: 'Pilatus dan antwoordde wederom en zeide tot hen: Wat wilt gij dan dat ik doen zal met Hem dien gij koning der Joden noemt?',
        13: 'Doch zij schreeuwden wederom: Kruisig Hem!',
        14: 'Pilatus nu zeide tot hen: Wat kwaads heeft Hij toch gedaan? — Maar des te meer schreeuwden zij: Kruisig Hem!',
        15: 'Pilatus nu, die aan de schare wilde voldoen, liet hun Barabbas los, en gaf Jezus over, nadat hij Hem gegeeseld had, opdat Hij zou gekruisigd worden.',
        16: 'De soldaten dan voerden Hem weg, naar binnen in den voorhof, dat is het rechthuis, en zij riepen den ganschen troep samen.',
        17: 'En zij deden Hem een purperen mantel om en zetten Hem een kroon op, die van doornen was gevlochten.',
        18: 'En zij begonnen Hem te begroeten: Wees gegroet, koning der Joden!',
        19: 'En zij sloegen op zijn hoofd met een riet, en spogen op Hem, en vielen voor Hem op de knieën en aanbaden Hem.',
        20: 'En toen zij Hem bespot hadden, trokken zij Hem het purperen kleed uit en deden Hem zijn eigen kleederen aan.',
        21: 'En zij voerden Hem weg om Hem te kruisigen, en dwongen zekeren Simon van Cyrene, die daar voorbijging en van den akker kwam— den vader van Alexander en Rufus— om zijn kruis op te nemen.',
        22: 'En zij brachten Hem naar de plaats Golgotha, dat wil zeggen: Plaats der doodshoofden.',
        23: 'En zij gaven Hem wijn met mirre gemengd; maar Hij nam dien niet.',
        24: 'En zij kruisigden Hem en verdeelden zijn kleederen, door het lot daarover te werpen, wat elk zou nemen.',
        25: 'En het was de derde ure toen zij Hem kruisigden.',
        26: 'En de aanwijzing zijner beschuldiging, boven Hem geschreven, was: De Koning der Joden.',
        27: 'En met Hem kruisigden zij twee moordenaars, den één aan zijn rechter– en den ander aan zijn linkerzijde.',
        28: 'En de schrifture is vervuld, die zegt: En met misdadigers is hij gerekend.',
        29: 'En de voorbijgangers lasterden Hem, en schudden hun hoofden en zeiden: Welaan, gij tempelafbreker en opbouwer in drie dagen!',
        30: 'verlos u zelven door af te komen van het kruis!',
        31: 'Desgelijks bespotten Hem ook de overpriesters onder malkander, met de schriftgeleerden, zeggende: Anderen heeft Hij verlost, zich zelven verlossen kan Hij niet!',
        32: 'die Christus, de koning Israëls! dat Hij nu afkome van het kruis, dat wij het zien en wij zullen gelooven! En ook die met Hem gekruisigd waren, beschimpten Hem.',
        33: 'En toen de zesde ure was gekomen werd er duisternis over de geheele aarde tot de negende ure toe.',
        34: 'En ter negender ure riep Jezus met een groote stem: Eloï, Eloï, lema sabachthanei, dat wil zeggen: Mijn God! mijn God! waartoe hebt Gij Mij verlaten?',
        35: 'En sommigen, die daarbij stonden en het hoorden, zeiden: Zie, Hij roept Elias!',
        36: 'En één liep er toe en vulde een spons met azijn en stak die op een rietstok en gaf Hem te drinken, zeggende: Wacht, laat ons zien of Elias komt om Hem af te nemen!',
        37: 'En Jezus riep met een luide stem en gaf den geest.',
        38: 'En het voorhangsel des tempels scheurde in tweeën van boven naar beneden.',
        39: 'En de hoofdman die er bij stond tegenover Hem, ziende dat Hij alzoo roepende den geest had gegeven, zeide: Waarlijk, deze mensch was Gods Zoon!',
        40: 'En er waren ook vrouwen, die het uit de verte aanschouwden, onder welke ook Maria Magdalena, en Maria, de moeder van Jakobus den jongere en van Joses, en Salome.',
        41: 'Deze volgden Hem reeds als Hij in Galilea was en dienden Hem; en vele anderen, die met Hem naar Jerusalem waren opgegaan.',
        42: 'En toen het nu avond was geworden, daar het voorbereiding was, dat is de voorsabbat,',
        43: 'kwam Jozef van Arimathea, een aanzienlijk raadsheer, die ook zelf het koninkrijk Gods verwachtende was; en hij verstoutte zich en ging tot Pilatus en verzocht om het lichaam van Jezus.',
        44: 'Doch Pilatus verwonderde zich dat Hij al zou gestorven zijn, en riep den hoofdman tot zich en vroeg hem of Hij al lang dood was.',
        45: 'En toen hij het van den hoofdman vernomen had, schonk hij het lichaam aan Jozef.',
        46: 'En deze kocht lijnwaad en, nadat hij Hem had afgenomen, wond hij Hem in het lijnwaad en leide Hem in een graf dat uit een steenrots was gekapt, en hij rolde een steen tegen de deur des grafs.',
        47: 'Maria Magdalena nu, en Maria de moeder van Joses zagen toe waar Hij gelegd werd.',
    },
    16: {
        1: 'En toen de sabbat voorbij was kochten Maria Magdalena, en Maria de moeder van Jakobus, en Salome welriekende kruiden om Jezus te gaan zalven.',
        2: 'En zeer vroeg, op den eersten dag der week, kwamen zij naar het graf, toen de zon aan het opgaan was.',
        3: 'En zij zeiden tot malkander: Wie zal voor ons den steen van voor de deur des grafs afwentelen?',
        4: 'En opziende zagen zij dat de steen afgewenteld was; — want hij was zeer groot.',
        5: 'En in het graf gegaan zijnde, zagen zij een jongeling zitten ter rechterzijde, gekleed met een lang, wit kleed, en zij verschrikten.',
        6: 'Maar hij zeide tot haar: Verschrikt niet! Jezus zoekt gij, den Nazarener, den gekruisigde; Hij is verrezen, Hij is hier niet! Zie de plaats waar zij Hem gelegd hebben.',
        7: 'Maar gaat heen, zegt tot zijn discipelen en tot Petrus, dat Hij u voorgaat naar Galilea; daar zult gij Hem zien, zooals Hij u gezegd heeft!',
        8: 'En zij gingen heen en vloden van het graf, want zij vreesden en beefden, en zeiden aan niemand iets, want zij waren bevreesd.',
        9: 'Toen Jezus nu des morgens vroeg was verrezen, op den eersten dag der week, verscheen Hij eerst aan Maria Magdalena, uit wie Hij zeven booze geesten had uitgeworpen.',
        10: 'Deze ging heen en boodschapte het aan degenen die met Hem geweest waren, die treurden en weenden.',
        11: 'En als dezen hoorden dat Hij leefde en door haar gezien was, geloofden zij het niet.',
        12: 'Daarna verscheen Hij in een andere gedaante aan twee van hen, die wandelden en naar het veld gingen.',
        13: 'Ook dezen gingen heen en boodschapten het aan de anderen; maar ook dezen geloofden zij niet.',
        14: 'Later verscheen Hij aan de elf apostelen toen zij aan tafel lagen, en verweet hun ongeloof en verharding des harten, omdat zij hen niet hadden geloofd die Hem gezien hadden, nadat Hij was verrezen.',
        15: 'En Hij zeide tot hen: Gaat heen door de geheele wereld, predikt het Evangelie aan alle schepsel.',
        16: 'Die geloofd zal hebben en gedoopt zal zijn die zal behouden worden, maar die niet geloofd zal hebben zal veroordeeld worden.',
        17: 'Dengenen nu, die geloofd zullen hebben, zullen deze teekenen volgen: In mijn Naam zullen zij booze geesten uitwerpen; met nieuwe tongen zullen zij spreken;',
        18: 'slangen zullen zij opnemen, en mochten zij iets doodelijks drinken, dat zal hun geenszins schaden; op kranken zullen zij de handen leggen en zij zullen genezen.',
        19: 'De Heere dan, nadat Hij tot hen gesproken had, is opgenomen naar den hemel en gezeten aan Gods rechterhand.',
        20: 'Zij nu gingen uit en predikten overal, terwijl de Heere medewerkte en het woord bekrachtigde door de teekenen die er op volgden.',
    },
}
